/* eslint-disable no-invalid-this */
/* eslint-disable no-underscore-dangle */
/* eslint-disable max-lines-per-function */
/* eslint-disable max-statements */
/* eslint-disable max-len */

'use strict';

// MODULES //

var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var colorsSet = require( './colors-set.js' );
var glyphsSet = require( './glyphs-set.js' );
var isLegal = require( './utils/is-valid-row-col.js' );


// FUNCTIONS //

/**
* Process a color.
* @private
* @param {string} colorCode color code
* @returns {string} color encoding
*/
function processColor( colorCode ) {
	return colorsSet[ colorCode ];
}

/**
* Process a glyph.
* @private
* @param {string} glyphCode glyph code
* @returns {string} glyph encoding
*/
function processGlyph( glyphCode ) {
	return glyphsSet[ glyphCode ];
}

/**
* Is intialized.
* @private
* @param {BasePlot} basePlot - BasePlot instance
* @returns {boolean} Is intialized
*/
function isInitialized( basePlot ) {
	var cond1;
	var cond2;

	cond1 = basePlot._backgroundColorMatrix.length && basePlot._foregroundColorMatrix.length && basePlot._glyphMatrix.length;
	cond2 = basePlot._plotArea && hasOwnProp( basePlot._plotArea, 'x' ) && hasOwnProp( basePlot._plotArea, 'y' ) && hasOwnProp( basePlot._plotArea, 'z' ) && hasOwnProp( basePlot._plotArea, 'w' );
	return cond1 && cond2;
}


// MAIN //

/**
* Render...
*
* @private
* @returns {string} render string
*/
function render() {
	var background;
	var foreground;
	var tmpQuite;
	var plotStr = '';
	var height;
	var width;
	var temp;
	var opts;
	var xPos;
	var yPos;
	var zPos;
	var wPos;
	var ptr;
	var pos;
	var val;
	var bl;
	var i;
	var j;

	if ( !isInitialized( this ) ) {
		return '';
	}

	// Setting axis position to actual row or column
	xPos = this.xAxisPos + this.xTicsLabelSpace;
	yPos = this.yAxisPos + this.yTicsLabelSpace;
	zPos = this.zAxisPos + this.xTicsLabelSpace;
	wPos = this.wAxisPos + this.yTicsLabelSpace;

	// Rendering the axis tics and label

	// x-axis
	if ( this._axisDataObjs[ 0 ].axis ) {
		// Setting labels area background color
		if ( this.ticsLabelsBckColor && this.ticsLabelsBckColor !== this.backgroundColor ) {
			bl = [ this.plotArea.y, xPos - this.xTicsLabelSpace ];
			height = this.plotArea.w - this.plotArea.y + 1;
			width = this.xTicsLabelSpace + 1;
			tmpQuite = this._quite;
			this._quite = true;
			opts = {
				'startPos': bl,
				'height': height,
				'width': width,
				'backgroundColor': this.ticsLabelsBckColor,
				'overwrite': true
			};
			this.setBar( opts );
			this._quite = tmpQuite;
		}

		// Labels and tics
		ptr = [ this.plotArea.y, xPos ];
		temp = this._axisDataObjs[ 0 ].normalizeLabels;
		pos = ptr[ 0 ];

		// Iterating from each labels
		for ( i = 0; i < temp.length && pos <= this.plotArea.w; i++ ) {
			val = temp[ i ].value;
			tmpQuite = this._quite;
			this._quite = true;
			this.setString({
				'row': pos,
				'column': ptr[ 1 ] - temp[ i ].width,
				'value': val,
				'overwrite': true
			});
			this._quite = tmpQuite;

			// Setting tic
			this.setGlyph( pos, ptr[ 1 ], this.verticalTicsGlyph, true );
			pos += this._axisDataObjs[ 0 ].ticsSpacing;
		}

		// Setting axis glyh
		pos = this.plotArea.y;
		for ( i = this.plotArea.y; i <= this.plotArea.w; i++ ) {
			this.setGlyph( i, ptr[ 1 ], this.verticalAxisGlyph, false );
			pos += 1;
		}
	}

	// y-axis

	if ( this._axisDataObjs[ 1 ].axis ) {
		// Setting labels area background color
		if ( this.ticsLabelsBckColor && this.ticsLabelsBckColor !== this.backgroundColor ) {
			bl = [ yPos - this.yTicsLabelSpace, this.plotArea.x ];
			height = this.yTicsLabelSpace + 1;
			width = this.plotArea.z - this.plotArea.x + 1;
			tmpQuite = this._quite;
			this._quite = true;
			opts = {
				'startPos': bl,
				'height': height,
				'width': width,
				'backgroundColor': this.ticsLabelsBckColor,
				'overwrite': true
			};
			this.setBar( opts );
			this._quite = tmpQuite;
		}

		// Rendering labels and tics
		ptr = [ yPos, this.plotArea.x ];
		temp = this._axisDataObjs[ 1 ].normalizeLabels;
		pos = ptr[ 1 ];

		// Iterating from each labels
		for ( i = 0; i < temp.length && pos <= this.plotArea.z; i++ ) {
			val = temp[ i ].value;

			// Labels should be of size of ticSpacing in horizontal axis
			val = val.substring( 0, this._axisDataObjs[ 1 ].ticsSpacing );
			tmpQuite = this._quite;
			this._quite = true;
			this.setString({
				'row': ptr[ 0 ] - 1,
				'column': pos,
				'value': val,
				'overwrite': true
			});
			this._quite = tmpQuite;

			// Setting tic
			this.setGlyph( ptr[ 0 ], pos, this.horizontalTicsGlyph, true );
			pos += this._axisDataObjs[ 1 ].ticsSpacing;
		}

		// Setting axis glyh
		for ( i = this.plotArea.x; i <= this.plotArea.z; i++ ) {
			this.setGlyph( ptr[ 0 ], i, this.horizontalAxisGlyph, false );
		}
	}

	// z-axis

	if ( this._axisDataObjs[ 2 ].axis ) {
		// Setting labels area background color
		if ( this.ticsLabelsBckColor && this.ticsLabelsBckColor !== this.backgroundColor ) {
			bl = [ this.plotArea.y, zPos ];
			height = this.plotArea.w - this.plotArea.y + 1;
			width = this.zTicsLabelSpace + 1;
			tmpQuite = this._quite;
			this._quite = true;
			opts = {
				'startPos': bl,
				'height': height,
				'width': width,
				'backgroundColor': this.ticsLabelsBckColor,
				'overwrite': true
			};
			this.setBar( opts );
			this._quite = tmpQuite;
		}

		// Label and tics
		ptr = [ this.plotArea.y + 1, zPos ];
		temp = this._axisDataObjs[ 2 ].normalizeLabels;
		pos = ptr[ 0 ];

		// Iterating from each labels
		for ( i = 0; i < temp.length && pos <= this.plotArea.w; i++ ) {
			val = temp[ i ].value;
			tmpQuite = this._quite;
			this._quite = true;
			this.setString({
				'row': pos,
				'column': ptr[ 1 ] + 1,
				'value': val,
				'overwrite': true
			});
			this._quite = tmpQuite;

			// Setting tic
			this.setGlyph( pos, ptr[ 1 ], this.verticalTicsGlyph, true );
			pos += this._axisDataObjs[ 2 ].ticsSpacing;
		}

		// Setting axis glyh
		for ( i = this.plotArea.y; i <= this.plotArea.w; i++ ) {
			this.setGlyph( i, ptr[ 1 ], this.verticalAxisGlyph, false );
		}
	}

	// w-axis

	if ( this._axisDataObjs[ 3 ].axis ) {
		// Setting labels area background color
		if ( this.ticsLabelsBckColor && this.ticsLabelsBckColor !== this.backgroundColor ) {
			bl = [ wPos, this.plotArea.x ];
			height = this.wTicsLabelSpace + 1;
			width = this.plotArea.z - this.plotArea.x + 1;
			tmpQuite = this._quite;
			this._quite = true;
			opts = {
				'startPos': bl,
				'height': height,
				'width': width,
				'backgroundColor': this.ticsLabelsBckColor,
				'overwrite': true
			};
			this.setBar( opts );
			this._quite = tmpQuite;
		}
		ptr = [ wPos, this.plotArea.x + 1 ];
		temp = this._axisDataObjs[ 3 ].normalizeLabels;
		pos = ptr[ 1 ];

		// Iterating from each labels
		for ( i = 0; i < temp.length && pos <= this.plotArea.z; i++ ) {
			val = temp[ i ].value;
			tmpQuite = this._quite;
			this._quite = true;
			this.setString({
				'row': ptr[ 0 ] + 1,
				'column': pos,
				'value': val,
				'overwrite': true
			});
			this._quite = tmpQuite;

			// Setting tic
			this.setGlyph( ptr[ 0 ], pos, this.horizontalTicsGlyph, true );
			pos += this._axisDataObjs[ 3 ].ticsSpacing;
		}

		// Setting axis glyh
		for ( i = this.plotArea.x; i <= this.plotArea.z; i++ ) {
			this.setGlyph( ptr[ 0 ], i, this.horizontalAxisGlyph, false );
		}
	}

	// Intersections glyph

	if ( this.xAxis && this.yAxis ) {
		this.setGlyph( yPos, xPos, this.axisIntersectionGlyph, true );
	}
	if ( this.wAxis && this.xAxis ) {
		this.setGlyph( wPos, xPos, this.axisIntersectionGlyph, true );
	}
	if ( this.wAxis && this.zAxis ) {
		this.setGlyph( wPos, zPos, this.axisIntersectionGlyph, true );
	}
	if ( this.yAxis && this.zAxis ) {
		this.setGlyph( yPos, zPos, this.axisIntersectionGlyph, true );
	}

	// Final Render...
	for ( i = this._height - 1; i >= 0; i-- ) {
		plotStr += '\r';
		for ( j = 0; j < this._width; j++ ) {
			// If background color is not same as previous then only we need to change it

			if ( !isLegal( i, j - 1, this._height, this._width ) || this._backgroundColorMatrix[ i ][ j ] !== this._backgroundColorMatrix[ i ][ j - 1 ] ) {
				background = processColor( this._backgroundColorMatrix[ i ][ j ] );
				plotStr += background;
			}

			// If forward color is not same as previous then only we need to change it

			if ( !isLegal( i, j - 1, this._height, this._width ) || this._foregroundColorMatrix[ i ][ j ] !== this._foregroundColorMatrix[ i ][ j - 1 ] ) {
				foreground = processColor( this._foregroundColorMatrix[ i ][ j ] );
				plotStr += foreground;
			}
			plotStr += processGlyph( this._glyphMatrix[ i ][ j ] );
		}
		plotStr += processColor( 'Default' );
		plotStr += '\n';
	}

	if ( this.autoRender ) {
		this.emit( 'render', plotStr );
	}
	return plotStr;
}


// EXPORTS //

module.exports = render;
